import { Event } from '@/types/schedule';

// Builds the raw ICS text for a list of events.
export function buildICSContent(events: Event[]): string {
  // Formats a Date to ICS UTC format (YYYYMMDDTHHMMSSZ).
  const formatICSDate = (date: Date) =>
    date.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';

  let icsContent =
    'BEGIN:VCALENDAR\r\n' +
    'VERSION:2.0\r\n' +
    'PRODID:-//11Planner//EN\r\n' +
    'CALSCALE:GREGORIAN\r\n' +
    'X-WR-CALNAME:11Planner Schedule\r\n' +
    'X-WR-CALDESC:Study blocks generated by 11Planner\r\n';

  events.forEach((event) => {
    icsContent += 'BEGIN:VEVENT\r\n';
    icsContent += `UID:${event.id || crypto.randomUUID()}@11planner\r\n`;
    icsContent += `DTSTAMP:${formatICSDate(new Date())}\r\n`;
    icsContent += `DTSTART:${formatICSDate(new Date(event.start))}\r\n`;
    icsContent += `DTEND:${formatICSDate(new Date(event.end))}\r\n`;

    const escapedTitle = event.title
      .replace(/[\\;,]/g, (match) => '\\' + match)
      .replace(/\n/g, '\\n');
    icsContent += `SUMMARY:${escapedTitle}\r\n`;

    if (event.description) {
      const escapedDesc = event.description
        .replace(/[\\;,]/g, (match) => '\\' + match)
        .replace(/\n/g, '\\n');
      icsContent += `DESCRIPTION:${escapedDesc}\r\n`;
    }

    icsContent += 'END:VEVENT\r\n';
  });

  icsContent += 'END:VCALENDAR\r\n';
  return icsContent;
}

// Opens the ICS data in the OS default calendar application.
// On macOS this triggers Apple Calendar; on Windows it triggers Outlook / Windows Calendar.
// Returns true if the open was attempted, false if there were no events.
export function openEventsInCalendar(events: Event[]): boolean {
  if (events.length === 0) return false;

  const icsContent = buildICSContent(events);
  const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
  const url = URL.createObjectURL(blob);

  // Create a hidden anchor and click it – the browser will route text/calendar
  // blobs to the system calendar on macOS / iOS / Windows.
  const link = document.createElement('a');
  link.href = url;
  link.setAttribute('download', '11planner-schedule.ics');
  link.setAttribute('type', 'text/calendar');
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  // Clean up the object URL after a brief delay.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
  return true;
}

// Serializes events to ICS and triggers a calendar file download.
export function exportEventsToICS(events: Event[], filename: string = '11planner-schedule.ics') {
  const icsContent = buildICSContent(events);

  const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
  const link = document.createElement('a');
  
  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }
}
